            "\u{092E}\u{093E}\u{0930}\u{094D}\u{091A}",         // à¤®à¤¾à¤°à¥à¤š
            "\u{0905}\u{092A}\u{094D}\u{0930}\u{0948}\u{0932}", // à¤…à¤ªà¥à¤°à¥ˆà¤²
            "\u{092E}\u{0908}",                                 // à¤®à¤ˆ
            "\u{091C}\u{0942}\u{0928}",                         // à¤œà¥‚à¤¨
            "\u{091C}\u{0941}\u{0932}\u{0970}",                 // à¤œà¥à¤²à¥°
            "\u{0905}\u{0917}\u{0970}",                         // à¤…à¤—à¥°
            "\u{0938}\u{093F}\u{0924}\u{0970}",                 // à¤¸à¤¿à¤¤à¥°
            "\u{0905}\u{0915}\u{094D}\u{0924}\u{0942}\u{0970}", // à¤…à¤•à¥à¤¤à¥‚à¥°
            "\u{0928}\u{0935}\u{0970}",                         // à¤¨à¤µà¥°
